package edu.smartstudy.planning;
import edu.smartstudy.user.UserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.LocalDate; import java.util.*;
import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/tasks") public class StudyTaskController { private final StudyTaskRepository tasks; private final UserRepository users; public StudyTaskController(StudyTaskRepository tasks,UserRepository users){this.tasks=tasks;this.users=users;} private Long owner(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();} public record TaskInput(@NotBlank @Size(max=255) String title,@Size(max=120) String subject,LocalDate scheduledDate,@Min(5) @Max(600) int estimatedMinutes,@Pattern(regexp="LOW|MEDIUM|HIGH") String priority){} @GetMapping public List<StudyTask> list(Authentication a){return tasks.findTop100ByStudentIdOrderByScheduledDateAscCreatedAtDesc(owner(a));} @PostMapping public ResponseEntity<?> create(@RequestBody @Valid TaskInput i,Authentication a){return ResponseEntity.status(201).body(tasks.save(new StudyTask(owner(a),null,i.title().trim(),i.subject(),i.scheduledDate(),i.estimatedMinutes(),i.priority()==null?"MEDIUM":i.priority())));} @PatchMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody @Valid TaskInput i,Authentication a){return tasks.findByIdAndStudentId(id,owner(a)).<ResponseEntity<?>>map(t->{t.update(i.title().trim(),i.subject(),i.scheduledDate(),i.estimatedMinutes(),i.priority()==null?"MEDIUM":i.priority());return ResponseEntity.ok(tasks.save(t));}).orElseGet(()->ResponseEntity.notFound().build());} @PostMapping("/{id}/complete") public ResponseEntity<?> complete(@PathVariable Long id,Authentication a){return tasks.findByIdAndStudentId(id,owner(a)).<ResponseEntity<?>>map(t->{t.complete();return ResponseEntity.ok(tasks.save(t));}).orElseGet(()->ResponseEntity.notFound().build());} @PostMapping("/{id}/reopen") public ResponseEntity<?> reopen(@PathVariable Long id,Authentication a){return tasks.findByIdAndStudentId(id,owner(a)).<ResponseEntity<?>>map(t->{t.reopen();return ResponseEntity.ok(tasks.save(t));}).orElseGet(()->ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id,Authentication a){var t=tasks.findByIdAndStudentId(id,owner(a));if(t.isEmpty())return ResponseEntity.notFound().build();tasks.delete(t.get());return ResponseEntity.noContent().build();} }
